var rrGolden map[string]any

func loadRRGolden(t *testing.T) map[string]any {
	t.Helper()
	if rrGolden != nil {
		return rrGolden
	}
	data, err := os.ReadFile("testdata/reporadar.golden.json")
	if err != nil {
		t.Fatalf("golden file: %v", err)
	}
	var g map[string]any
	if err := json.Unmarshal(data, &g); err != nil {
		t.Fatalf("golden json: %v", err)
	}
	rrGolden = g
	return g
}

func rrSection(t *testing.T, name string) map[string]any {
	t.Helper()
	v, ok := loadRRGolden(t)[name].(map[string]any)
	if !ok {
		t.Fatalf("golden section %q missing or not an object", name)
	}
	return v
}

func rrValue(t *testing.T, name string) any {
	t.Helper()
	v, ok := loadRRGolden(t)[name]
	if !ok {
		t.Fatalf("golden value %q missing", name)
	}
	return v
}

// cmpRRGolden compares through the canonical Python dumps (maps sort
// keys; slices keep order) so the comparison is byte-honest.
func cmpRRGolden(t *testing.T, what string, got, want any) {
	t.Helper()
	g := storage.PyDumps(normRR(got))
	w := storage.PyDumps(normRR(want))
	if g != w {
		t.Errorf("%s diverges from the reference golden:\n got: %s\nwant: %s",
			what, g, w)
	}
}

// normRR normalizes Go values and JSON-decoded golden values onto the
// same comparable shape (the vaultseal normVS twin).
func normRR(v any) any {
	switch t := v.(type) {
	case string:
		return t
	case int:
		return float64(t)
	case int64:
		return float64(t)
	case bool, float64, nil:
		return t
	case json.Number:
		f, _ := t.Float64()
		return f
	case *storage.OrderedMap:
		if t == nil {
			return nil
		}
		out := map[string]any{}
		for _, k := range t.Keys() {
			val, _ := t.Get(k)
			out[k] = normRR(val)
		}
		return out
	case map[string]any:
		if t == nil { // a nil map is Python's None, not {}
			return nil
		}
		out := map[string]any{}
		for k, val := range t {
			out[k] = normRR(val)
		}
		return out
	case map[string]bool:
		if t == nil {
			return nil
		}
		out := map[string]any{}
		for k, val := range t {
			out[k] = val
		}
		return out
	case map[string]string:
		out := map[string]any{}
		for k, val := range t {
			out[k] = val
		}
		return out
	case map[string]int:
		out := map[string]any{}
		for k, val := range t {
			out[k] = float64(val)
		}
		return out
	case []any:
		if t == nil { // Python list-typed returns are [], never None
			return []any{}
		}
		out := make([]any, len(t))
		for i, val := range t {
			out[i] = normRR(val)
		}
		return out
	case []string:
		if t == nil {
			return []any{}
		}
		out := make([]any, len(t))
		for i, s := range t {
			out[i] = s
		}
		return out
	case []int:
		out := make([]any, len(t))
		for i, n := range t {
			out[i] = float64(n)
		}
		return out
	case *Detection:
		return normRR(t.Map())
	default:
		return fmt.Sprintf("%v", v)
	}
}

// foldRR folds the Go run's temp root away (the generator's fold
// twin): root → '<root>'.
func foldRR(obj any, root string) any {
	switch t := obj.(type) {
	case string:
		if root != "" && strings.HasPrefix(t, root) {
			return "<root>" + t[len(root):]
		}
		return t
	case *storage.OrderedMap:
		out := storage.NewOrderedMap()
		for _, k := range t.Keys() {
			v, _ := t.Get(k)
			out.Set(k, foldRR(v, root))
		}
		return out
	case map[string]any:
		out := map[string]any{}
		for k, v := range t {
			out[k] = foldRR(v, root)
		}
		return out
	case []any:
		out := make([]any, len(t))
		for i, v := range t {
			out[i] = foldRR(v, root)
		}
		return out
	case []string:
		out := make([]any, len(t))
		for i, v := range t {
			out[i] = foldRR(v, root)
		}
		return out
	default:
		return obj
	}
}

// detectionDict answers the Detection as a folded dict (dict(Detection)'s
// JSON shape — the "" kwargs stay "" exactly like the reference).
func detectionDict(det *Detection, root string) map[string]any {
	m := map[string]any{}
	for _, k := range det.Map().Keys() {
		v, _ := det.Map().Get(k)
		m[k] = v
	}
	return foldRR(m, root).(map[string]any)
}

// goldenVault mirrors the generator's _make_vault (sorted write
// order).
func goldenVault(t *testing.T, tmp, name string, files map[string]string) string {
	t.Helper()
	root := filepath.Join(tmp, name)
	if err := os.MkdirAll(root, 0o755); err != nil {
		t.Fatal(err)
	}
	keys := make([]string, 0, len(files))
	for k := range files {
		keys = append(keys, k)
	}
	sortStrings(keys)
	for _, rel := range keys {
		writeVaultFile(t, root, rel, files[rel])
	}
	return root
}

// goldenRemoteVault mirrors the generator's _make_remote_vault.
func goldenRemoteVault(t *testing.T, tmp, name, owner, repo string) string {
	t.Helper()
	root := goldenVault(t, tmp, name, map[string]string{"note.md": "# hi\n"})
	out, err := exec.Command("git", "-C", root, "init", "-b", "main").CombinedOutput()
	if err != nil {
		t.Fatalf("git init: %v\n%s", err, out)
	}
	cfg := filepath.Join(root, ".git", "config")
	f, err := os.OpenFile(cfg, os.O_APPEND|os.O_WRONLY, 0o644)
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()
	if _, err := f.WriteString("[remote \"origin\"]\n\turl = https://github.com/" +
		owner + "/" + repo + ".git\n"); err != nil {
		t.Fatal(err)
	}
	return root
}

// goldenAPI mirrors the generator's FakeAPI (the plain shape — no
// call recording).
func goldenAPI(opts func(*fakeRadarAPI)) *fakeRadarAPI { return newFakeAPI(opts) }

// noneIfEmpty boxes the empty string as null (the Python None door)
// for golden comparisons.
func noneIfEmpty(s string) any {
	if s == "" {
		return nil
	}
	return s
}

