func TestGolden_RemoteAndBlobs(t *testing.T) {
	want := rrSection(t, "parse_remote_repo")
	inputs := map[string]string{
		"https":         "https://github.com/owner/repo",
		"https_git":     "https://github.com/owner/repo.git",
		"https_slash":   "https://github.com/owner/repo/",
		"git_at":        "git@github.com:owner/repo.git",
		"ssh":           "ssh://git@github.com/owner/repo.git",
		"owner_lower":   "https://github.com/Owner/Repo",
		"gitlab":        "https://gitlab.com/owner/repo",
		"empty":         "",
		"git_not_owner": "https://github.com/git/x",
		"noise":         "https://github.com/aaa/aaa.git/tree/main",
	}
	for name, in := range inputs {
		cmpRRGolden(t, "parse_remote_repo."+name, noneIfEmpty(ParseRemoteRepo(in)), want[name])
	}

	bs := rrSection(t, "blob_sha")
	cmpRRGolden(t, "blob_sha.empty", BlobSha([]byte("")), bs["empty"])
	cmpRRGolden(t, "blob_sha.hello", BlobSha([]byte("hello\n")), bs["hello"])
	cmpRRGolden(t, "blob_sha.same", BlobSha([]byte("same")), bs["same"])
	cmpRRGolden(t, "blob_sha.unicode", BlobSha([]byte("unicode ⭐ content\n")), bs["unicode"])
	cmpRRGolden(t, "blob_sha.larger",
		BlobSha([]byte("# the personal vault\n"+strings.Repeat("y", 1100))), bs["larger"])
}

func TestGolden_Sampling(t *testing.T) {
	want := rrSection(t, "sample_vault_files")
	tmp := t.TempDir()
	files := map[string]string{}
	for i := 0; i < 30; i++ {
		files[fmt.Sprintf("big/f%02d.md", i)] = "x"
	}
	for i := 0; i < 3; i++ {
		files[fmt.Sprintf("sml/a%d.md", i)] = "y"
	}
	files["root.md"] = "r"
	files["notes/n.md"] = "n"
	files[".git/config"] = "junk"
	files[".trash/old.md"] = "x"
	files["sub/.DS_Store/file.md"] = "d"
	vault := goldenVault(t, tmp, "vault", files)

	cmpRRGolden(t, "sample.round_robin", SampleVaultFiles(vault, 10, 0), want["round_robin"])
	cmpRRGolden(t, "sample.default_cap", SampleVaultFiles(vault, 0, 0), want["default_cap"])
	cmpRRGolden(t, "sample.all_small", SampleVaultFiles(vault, 100, 0), want["all_small"])
	cmpRRGolden(t, "sample.blank", SampleVaultFiles("", 0, 0), want["blank"])
	cmpRRGolden(t, "sample.spaces", SampleVaultFiles("   ", 0, 0), want["spaces"])
	cmpRRGolden(t, "sample.missing",
		SampleVaultFiles(filepath.Join(tmp, "gone"), 0, 0), want["missing"])
}

