func TestGolden_Fingerprint(t *testing.T) {
	cand := rrSection(t, "fingerprint_candidates")

	var crowd []map[string]any
	for i := 0; i < 20; i++ {
		crowd = append(crowd, repoPayload(fmt.Sprintf("filler-%02d-vault", i), 5000, "main", false, false))
	}
	crowd = append(crowd, repoPayload("Ali-personal-obsidian-vault", 0, "main", false, false))
	cmpRRGolden(t, "candidates.crowding",
		namesOf(fingerprintCandidates(crowd, "renamed")), cand["crowding"])

	cmpRRGolden(t, "candidates.archived_fork_filtered",
		namesOf(fingerprintCandidates([]map[string]any{
			repoPayload("archived-backup", 5000, "main", true, false),
			repoPayload("forked-backup", 5000, "main", false, true),
			repoPayload("live-backup", 1000, "main", false, false),
		}, "v")), cand["archived_fork_filtered"])

	cmpRRGolden(t, "candidates.name_overlap_ranks",
		namesOf(fingerprintCandidates([]map[string]any{
			repoPayload("zeta-unrelated", 1000, "main", false, false),
			repoPayload("my-github-vault-notes", 1000, "main", false, false),
			repoPayload("alpha-vault", 1000, "main", false, false),
			repoPayload("beta-random", 1000, "main", false, false),
		}, "github-vault")), cand["name_overlap_ranks"])

	cmpRRGolden(t, "candidates.empty",
		namesOf(fingerprintCandidates(nil, "v")), cand["empty"])

	// -- the dominance ladder itself ------------------------------------
	fp := rrSection(t, "fingerprint")
	tmp := t.TempDir()
	files := map[string]string{}
	for i := 0; i < 6; i++ {
		files[fmt.Sprintf("n%d.md", i)] = fmt.Sprintf("# note %d\n", i) + strings.Repeat("z", 50)
	}
	vault := goldenVault(t, tmp, "moved-vault", files)
	api := goldenAPI(func(f *fakeRadarAPI) {
		f.repos = []map[string]any{rp("the-real-backup"), rp("something-else")}
		f.trees["owner/the-real-backup"] = shasOf(files)
		f.trees["owner/something-else"] = []string{gitBlob("unrelated")}
	})
	cmpRRGolden(t, "fingerprint.dominant",
		fpTuple(fingerprint(vault, api.repos, api, "moved-vault")), fp["dominant"])
	cmpRRGolden(t, "fingerprint.empty_vault",
		fpTuple(fingerprint(filepath.Join(tmp, "not-there"), api.repos, api, "moved-vault")),
		fp["empty_vault"])

	files2 := map[string]string{}
	for i := 0; i < 4; i++ {
		files2[fmt.Sprintf("n%d.md", i)] = fmt.Sprintf("# note %d\n", i)
	}
	vault2 := goldenVault(t, tmp, "v2", files2)
	api2 := goldenAPI(func(f *fakeRadarAPI) {
		f.repos = []map[string]any{rp("twin-a"), rp("twin-b")}
		f.trees["owner/twin-a"] = shasOf(files2)
		f.trees["owner/twin-b"] = shasOf(files2)
	})
	cmpRRGolden(t, "fingerprint.ambiguous",
		fpTuple(fingerprint(vault2, api2.repos, api2, "v2")), fp["ambiguous"])

	files3 := map[string]string{}
	for i := 0; i < 5; i++ {
		files3[fmt.Sprintf("n%d.md", i)] = fmt.Sprintf("# note %d\n", i)
	}
	vault3 := goldenVault(t, tmp, "v3", files3)
	api3 := goldenAPI(func(f *fakeRadarAPI) {
		f.repos = []map[string]any{rp("solo")}
		f.trees["owner/solo"] = shasOf(files3)[:2]
	})
	cmpRRGolden(t, "fingerprint.weak",
		fpTuple(fingerprint(vault3, api3.repos, api3, "v3")), fp["weak"])

	api4 := goldenAPI(func(f *fakeRadarAPI) {
		f.repos = []map[string]any{rp("other")}
		f.trees["owner/other"] = []string{gitBlob("unrelated")}
	})
	cmpRRGolden(t, "fingerprint.none",
		fpTuple(fingerprint(vault3, api4.repos, api4, "v3")), fp["none"])
}

// fpTuple boxes the fingerprint result as the reference's tuple list.
func fpTuple(r fingerprintResult) []any {
	var repo any
	if r.repo != "" {
		repo = r.repo
	}
	return []any{repo, r.matched, r.sampled, r.candidate, r.why}
}

func namesOf(repos []map[string]any) []string {
	var out []string
	for _, r := range repos {
		out = append(out, fmt.Sprintf("%v", r["name"]))
	}
	return out
}

func shasOf(files map[string]string) []string {
	keys := make([]string, 0, len(files))
	for k := range files {
		keys = append(keys, k)
	}
	sortStrings(keys)
	var out []string
	for _, k := range keys {
		out = append(out, gitBlob(files[k]))
	}
	return out
}

