func TestGolden_DetectBackupRepo(t *testing.T) {
	want := rrSection(t, "detect_backup_repo")
	tmp := t.TempDir()
	ROOT := tmp // the fold root (the generator's twin)

	det := func(kind, path string, api API, owner string) map[string]any {
		return detectionDict(DetectBackupRepo(kind, path, api, owner), ROOT)
	}

	cmpRRGolden(t, "detect.no_path", det("github", "", goldenAPI(nil), "owner"), want["no_path"])
	cmpRRGolden(t, "detect.no_owner", det("github", "/v", goldenAPI(nil), ""), want["no_owner"])

	remoteVault := goldenRemoteVault(t, tmp, "Ali-personal-obsidian-vault",
		"assadigit", "Ali-personal-obsidian-vault")
	apiRemote := goldenAPI(func(f *fakeRadarAPI) {
		f.exists["assadigit/Ali-personal-obsidian-vault"] =
			map[string]any{"name": "Ali-personal-obsidian-vault"}
	})
	cmpRRGolden(t, "detect.remote_certain",
		det("personal", remoteVault, apiRemote, "assadigit"), want["remote_certain"])

	ghostVault := goldenRemoteVault(t, tmp, "v", "owner", "ghost-repo")
	apiGhost := goldenAPI(func(f *fakeRadarAPI) {
		f.exists["owner/ghost-repo"] = map[string]any{"_error": "HTTP 403"}
	})
	cmpRRGolden(t, "detect.remote_unverifiable",
		det("github", ghostVault, apiGhost, "owner"), want["remote_unverifiable"])

	nameVault := goldenVault(t, tmp, "github-projects-obsidian-vault",
		map[string]string{"n.md": "x"})
	apiName := goldenAPI(func(f *fakeRadarAPI) {
		f.exists["owner/github-projects-obsidian-vault"] =
			map[string]any{"name": "github-projects-obsidian-vault"}
	})
	cmpRRGolden(t, "detect.name_certain",
		det("github", nameVault, apiName, "owner"), want["name_certain"])

	promised := filepath.Join(tmp, "my-awesome-websites-directory")
	apiPromised := goldenAPI(func(f *fakeRadarAPI) {
		f.exists["owner/my-awesome-websites-directory"] =
			map[string]any{"name": "my-awesome-websites-directory"}
	})
	cmpRRGolden(t, "detect.name_not_yet_created",
		det("websites", promised, apiPromised, "owner"), want["name_not_yet_created"])

	files := map[string]string{}
	for i := 0; i < 6; i++ {
		files[fmt.Sprintf("n%d.md", i)] = fmt.Sprintf("# note %d\n", i) + strings.Repeat("z", 50)
	}
	fpVault := goldenVault(t, tmp, "moved-vault", files)
	apiFp := goldenAPI(func(f *fakeRadarAPI) {
		f.repos = []map[string]any{rp("the-real-backup"), rp("something-else")}
		f.trees["owner/the-real-backup"] = shasOf(files)
		f.trees["owner/something-else"] = []string{gitBlob("unrelated")}
	})
	cmpRRGolden(t, "detect.fingerprint_dominant",
		det("github", fpVault, apiFp, "owner"), want["fingerprint_dominant"])

	content := "# the personal vault\n" + strings.Repeat("y", 1100)
	zeroVault := goldenVault(t, tmp, "renamed-folder",
		map[string]string{"README.md": content})
	apiZero := goldenAPI(func(f *fakeRadarAPI) {
		f.repos = []map[string]any{repoPayload("Ali-personal-obsidian-vault", 0, "main", false, false)}
		f.trees["owner/Ali-personal-obsidian-vault"] = []string{gitBlob(content)}
	})
	cmpRRGolden(t, "detect.size_zero",
		det("personal", zeroVault, apiZero, "owner"), want["size_zero"])

	files3 := map[string]string{}
	for i := 0; i < 4; i++ {
		files3[fmt.Sprintf("n%d.md", i)] = fmt.Sprintf("# note %d\n", i)
	}
	twinVault := goldenVault(t, tmp, "v3", files3)
	apiTwin := goldenAPI(func(f *fakeRadarAPI) {
		f.repos = []map[string]any{rp("twin-a"), rp("twin-b")}
		f.trees["owner/twin-a"] = shasOf(files3)
		f.trees["owner/twin-b"] = shasOf(files3)
	})
	cmpRRGolden(t, "detect.ambiguity",
		det("github", twinVault, apiTwin, "owner"), want["ambiguity"])
	apiWeak := goldenAPI(func(f *fakeRadarAPI) {
		f.repos = []map[string]any{rp("solo")}
		f.trees["owner/solo"] = shasOf(files3)[:2]
	})
	cmpRRGolden(t, "detect.weak",
		det("github", twinVault, apiWeak, "owner"), want["weak"])
	apiNone := goldenAPI(func(f *fakeRadarAPI) {
		f.repos = []map[string]any{rp("other")}
		f.trees["owner/other"] = []string{gitBlob("unrelated")}
	})
	cmpRRGolden(t, "detect.no_match",
		det("github", twinVault, apiNone, "owner"), want["no_match"])
	cmpRRGolden(t, "detect.missing_folder_law",
		det("github", filepath.Join(tmp, "no-such-vault-yet"), goldenAPI(nil), "owner"),
		want["missing_folder_law"])
}

