func TestGolden_RadarAllVaults(t *testing.T) {
	want := rrSection(t, "radar_all_vaults")
	tmp := t.TempDir()

	dumpRadar := func(cfg map[string]any, api API) map[string]any {
		out := map[string]any{}
		for kind, det := range RadarAllVaults(cfg, api) {
			out[kind] = detectionDict(det, tmp)
		}
		return out
	}

	cmpRRGolden(t, "radar.no_token",
		dumpRadar(map[string]any{"github_token": "", "vault_path": "/v"}, nil), want["no_token"])
	cmpRRGolden(t, "radar.rejected",
		dumpRadar(map[string]any{"github_token": "tok", "vault_path": "/v"},
			goldenAPI(func(f *fakeRadarAPI) { f.meOK = false })), want["rejected"])

	gh := goldenVault(t, tmp, "github-projects-obsidian-vault", map[string]string{"a.md": "x"})
	web := goldenVault(t, tmp, "my-awesome-websites-directory", map[string]string{"b.md": "y"})
	per := goldenVault(t, tmp, "Ali-personal-obsidian-vault", map[string]string{"c.md": "z"})
	api := goldenAPI(func(f *fakeRadarAPI) {
		f.exists["owner/github-projects-obsidian-vault"] =
			map[string]any{"name": "github-projects-obsidian-vault"}
		f.exists["owner/my-awesome-websites-directory"] =
			map[string]any{"name": "my-awesome-websites-directory"}
		f.exists["owner/Ali-personal-obsidian-vault"] =
			map[string]any{"name": "Ali-personal-obsidian-vault"}
	})
	cmpRRGolden(t, "radar.all_detected",
		dumpRadar(map[string]any{
			"github_token": "tok", "vault_path": gh,
			"website_vault_path": web, "manual_vault_path": per,
		}, api), want["all_detected"])
	cmpRRGolden(t, "radar.owner_kept",
		dumpRadar(map[string]any{
			"github_token": "tok", "vault_path": gh,
			"vaultseal":          map[string]any{"repo_name": "my-own-choice"},
			"website_vault_path": web, "manual_vault_path": per,
		}, api), want["owner_kept"])
	cmpRRGolden(t, "radar.missing_path",
		dumpRadar(map[string]any{"github_token": "tok"}, goldenAPI(nil)), want["missing_path"])

	// the never-raises doors: a PANICKING API surface is recovered and
	// spoken (the reference's BoomAPI raise doors)
	cmpRRGolden(t, "radar.boom_me",
		dumpRadar(map[string]any{"github_token": "tok", "vault_path": "/v"},
			&boomMe{}), want["boom_me"])
	cmpRRGolden(t, "radar.boom_later",
		dumpRadar(map[string]any{"github_token": "tok", "vault_path": "/v"},
			&boomRepoExists{fakeRadarAPI{login: "owner", meOK: true}}), want["boom_later"])
}

// ---------------------------------------------------------------------------
// apply_detections / report_lines / radar_pending / the slot grammar
// ---------------------------------------------------------------------------

func TestGolden_ApplyReportPending(t *testing.T) {
	want := loadRRGolden(t)
	ad := want["apply_detections"].(map[string]any)

	results := map[string]any{
		"github":   NewDetection("kind", "github", "repo_name", "gh-repo", "confidence", "certain"),
		"websites": NewDetection("kind", "websites", "repo_name", "", "detail", "nothing"),
		"personal": NewDetection("kind", "personal", "repo_name", "per-repo", "confidence", "strong"),
	}
	cfg := map[string]any{}
	cmpRRGolden(t, "apply.applied", ApplyDetections(cfg, results), ad["applied"])
	cmpRRGolden(t, "apply.cfg", cfg, ad["cfg"])
	cmpRRGolden(t, "apply.again", ApplyDetections(cfg, results), ad["again"])

	ownerCfg := map[string]any{"website_repo_name": "typed-by-owner"}
	ownerResults := map[string]any{
		"github":   results["github"],
		"websites": NewDetection("kind", "websites", "repo_name", "detected", "confidence", "owner"),
		"personal": results["personal"],
	}
	cmpRRGolden(t, "apply.owner_never", ApplyDetections(ownerCfg, ownerResults), ad["owner_never"])

	plainCfg := map[string]any{}
	cmpRRGolden(t, "apply.plain_dicts", ApplyDetections(plainCfg, map[string]any{
		"github":   map[string]any{"repo_name": "gh-repo", "confidence": "certain"},
		"websites": map[string]any{"repo_name": "", "confidence": ""},
		"personal": map[string]any{"repo_name": "p", "confidence": "strong"},
	}), ad["plain_dicts"])
	cmpRRGolden(t, "apply.garbage_none", ApplyDetections(map[string]any{}, nil), ad["garbage_none"])
	cmpRRGolden(t, "apply.garbage_junk",
		ApplyDetections(map[string]any{}, map[string]any{"github": "junk"}), ad["garbage_junk"])
	cmpRRGolden(t, "apply.garbage_cfg", ApplyDetections(nil, map[string]any{}), ad["garbage_cfg"])

	// -- report_lines ------------------------------------------------------
	rl := want["report_lines"].(map[string]any)
	cmpRRGolden(t, "report.mixed", ReportLines(map[string]any{
		"github":   NewDetection("kind", "github", "repo_name", "gh", "confidence", "owner", "method", "config"),
		"websites": NewDetection("kind", "websites", "repo_name", "web", "confidence", "certain", "method", "name"),
		"personal": NewDetection("kind", "personal", "repo_name", "", "vault_path", "/p", "detail", "nothing conclusive"),
	}), rl["mixed"])
	cmpRRGolden(t, "report.plain", ReportLines(map[string]any{
		"github": map[string]any{"repo_name": "x", "confidence": "certain", "method": "remote"},
	}), rl["plain"])
	cmpRRGolden(t, "report.fingerprint_line", ReportLines(map[string]any{
		"personal": NewDetection("kind", "personal", "repo_name", "r", "confidence", "strong", "method", "fingerprint"),
	}), rl["fingerprint_line"])
	cmpRRGolden(t, "report.not_configured", ReportLines(map[string]any{
		"personal": NewDetection("kind", "personal", "repo_name", "", "vault_path", "", "detail", "x"),
	}), rl["not_configured"])

	// -- radar_pending -------------------------------------------------------
	rp := want["radar_pending"].(map[string]any)
	cmpRRGolden(t, "pending.no_token", RadarPending(map[string]any{
		"vault_path": "/v", "vaultseal": map[string]any{"repo_name": ""},
	}), rp["no_token"])
	cmpRRGolden(t, "pending.token_path_empty_slot", RadarPending(map[string]any{
		"github_token": "t", "vault_path": "/v"}), rp["token_path_empty_slot"])
	cmpRRGolden(t, "pending.fully_wired", RadarPending(map[string]any{
		"github_token": "t", "vault_path": "/v",
		"vaultseal":          map[string]any{"repo_name": "a"},
		"website_vault_path": "/w", "website_repo_name": "b",
		"manual_vault_path": "/p", "manual_repo_name": "c",
	}), rp["fully_wired"])
	cmpRRGolden(t, "pending.one_empty", RadarPending(map[string]any{
		"github_token": "t", "vault_path": "/v",
		"vaultseal":          map[string]any{"repo_name": "a"},
		"website_vault_path": "/w", "website_repo_name": "b",
		"manual_vault_path": "/p",
	}), rp["one_empty"])
	cmpRRGolden(t, "pending.no_paths",
		RadarPending(map[string]any{"github_token": "t"}), rp["no_paths"])
	cmpRRGolden(t, "pending.empty", RadarPending(map[string]any{}), rp["empty"])

	// -- the slot grammar ------------------------------------------------------
	sv := want["slot_value"].(map[string]any)
	cmpRRGolden(t, "slot_value.flat",
		slotValue(map[string]any{"website_repo_name": "x"}, "website_repo_name"), sv["flat"])
	cmpRRGolden(t, "slot_value.nested",
		slotValue(map[string]any{"vaultseal": map[string]any{"repo_name": "y"}},
			"vaultseal.repo_name"), sv["nested"])
	cmpRRGolden(t, "slot_value.nested_missing",
		slotValue(map[string]any{}, "vaultseal.repo_name"), sv["nested_missing"])
	cmpRRGolden(t, "slot_value.nested_not_dict",
		slotValue(map[string]any{"vaultseal": "junk"}, "vaultseal.repo_name"), sv["nested_not_dict"])
	cmpRRGolden(t, "slot_value.absent",
		slotValue(map[string]any{}, "manual_repo_name"), sv["absent"])
	cmpRRGolden(t, "slot_value.blank",
		slotValue(map[string]any{"manual_repo_name": "  "}, "manual_repo_name"), sv["blank"])

	ss := want["slot_set"].(map[string]any)
	cfg2 := map[string]any{"vaultseal": map[string]any{"enabled": true, "auto_push": false}}
	setSlotValue(cfg2, "vaultseal.repo_name", "set-once")
	// the generator's cfg dict is a LIVE reference — by dump time the
	// follow-up calls have rewritten it to the final state; the Go side
	// mirrors the full sequence before comparing.
	changed := setSlotValue(cfg2, "vaultseal.repo_name", "set-twice")
	unchanged := setSlotValue(cfg2, "vaultseal.repo_name", "set-twice")
	cmpRRGolden(t, "slot_set.cfg", cfg2, ss["cfg"])
	cmpRRGolden(t, "slot_set.changed", changed, ss["changed"])
	cmpRRGolden(t, "slot_set.unchanged", unchanged, ss["unchanged"])
	cfg3 := map[string]any{}
	setSlotValue(cfg3, "manual_repo_name", "flat")
	cmpRRGolden(t, "slot_set.flat_created", cfg3, ss["flat_created"])
}
